import { useState } from "react";

const BirthdayCake = () => {
  const [candlesLit, setCandlesLit] = useState(true);
  const birthdayDate = "Febrary 21, 2025";
  const today = new Date().toLocaleDateString();

  const blowOutCandles = () => {
    setCandlesLit(false);
  };

  return (
    <div className="cake-container">
      {today === birthdayDate ? (
        <h2> Birthday Party on {birthdayDate}! </h2>
      ) : (
        <p>something</p>
      )}
      {candlesLit ? (
        <button onClick={setCandlesLit(false)}>Blow Out Candles</button>
      ) : (
        <button>Drink Something!</button>
      )}
    </div>
  );
};

export default BirthdayCake;
